import java.util.Scanner;
public class FibonacciSeries {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int first = 0;
        int second = 1;
        if (n >= 1) {
            System.out.print(first);
        }
        if (n >= 2) {
            System.out.print(" " + second);
        }
        for (int i = 3; i <= n; i++) {
            int next = first + second;
            System.out.print(" " + next);
            first = second;
            second = next;
        }
    }
}

import java.util.Scanner;
public class FibonacciPosition {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int position = sc.nextInt();
        int first = 0;
        int second = 1;
        if (position == 1) {
            System.out.println(first);
        } else if (position == 2) {
            System.out.println(second);
        } else {
            for (int i = 3; i <= position; i++) {
                int next = first + second;
                first = second;
                second = next;
            }
            System.out.println(second);
        }
    }
}

import java.util.Scanner;
public class ArithmeticProgression {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int firstTerm = sc.nextInt();
        int difference = sc.nextInt();
        int n = sc.nextInt();
        int term = firstTerm;
        for (int i = 1; i <= n; i++) {
            System.out.print(term);
            if (i < n) {
                System.out.print(" ");
            }
            term = term + difference;
        }
    }
}

import java.util.Scanner;
public class GeometricProgression {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int firstTerm = sc.nextInt();
        int ratio = sc.nextInt();
        int n = sc.nextInt();
        int term = firstTerm;
        for (int i = 1; i <= n; i++) {
            System.out.print(term);
            if (i < n) {
                System.out.print(" ");
            }
            term = term * ratio;
        }
    }
}

import java.util.Scanner;
public class PowersOfTwo {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        for (int exponent = 0; exponent < n; exponent++) {
            int value = (int) Math.pow(2, exponent);
            System.out.print(value);
            if (exponent < n - 1) {
                System.out.print(" ");
            }
        }
    }
}

import java.util.Scanner;
class Calculator {
    int a, b;
    int add() { return a + b; }
    int subtract() { return a - b; }
    int multiply() { return a * b; }
    double divide() { return (double) a / b; }
}
public class CalculatorDemo {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        Calculator calculator = new Calculator();
        calculator.a = sc.nextInt();
        calculator.b = sc.nextInt();
        System.out.println("Addition = " + calculator.add());
        System.out.println("Subtraction = " + calculator.subtract());
        System.out.println("Multiplication = " + calculator.multiply());
        if (calculator.b == 0)
            System.out.println("Division is not defined");
        else
            System.out.println("Division = " + calculator.divide());
    }
}

